#nullable enable
using Wolverine.Http;
using Wolverine.Marten;
using Campaigns.Contracts;

namespace Campaigns.Slices.Campaigns;

/// <summary>
/// A state change on an existing stream, so the aggregate handler workflow fits: <c>[WriteAggregate]</c>
/// fetches the stream, folds it live, and carries its version into the append.
///
/// <c>(IResult, Events)</c> in that order, and <c>Required = false</c> so the decider answers for a
/// missing stream itself rather than letting the framework return a 404 with no rule name in it. Both
/// choices, and the three wrong ways to return from here, are worked through in
/// reference-implementations/state-change/.
/// </summary>
public static class CloseCampaignEndpoint
{
    public const string Route = "/campaigns/{campaignId}/close";

    [WolverinePost(Route)]
    public static (IResult, Events) Close(
        CloseCampaign command,
        [WriteAggregate(nameof(CloseCampaign.CampaignId), Required = false)] CloseCampaignState? campaign)
    {
        var events = new Events();

        // AlreadyClosed — needs the FOLD. A missing stream and a stream nobody opened fold the same.
        if (campaign is not { Exists: true })
            return (Rejections.Problem("NotOpened",
                $"No campaign {command.CampaignId} exists, so there is nothing to close."), events);

        if (campaign.Closed)
            return (Rejections.Problem("AlreadyClosed",
                $"Campaign {command.CampaignId} is already closed."), events);

        events += new CampaignClosed(command.CampaignId, DateTimeOffset.UtcNow);
        return (Results.NoContent(), events);
    }
}

